  "to": ["{{ $json.body.email }}"],
  "subject": "Welcome to NIRVANA MART, {{ $json.body.name }}! 🎓",
  "html": {{ JSON.stringify(`<div style='font-family:Segoe UI,sans-serif;max-width:600px;margin:0 auto;background:#f5f5f5;padding:24px;border-radius:12px;'><div style='background:linear-gradient(135deg,#0a0a14,#1a102a);padding:32px;border-radius:10px;text-align:center;margin-bottom:24px;'><img src='https://nirvana-mart.onrender.com/LOGO.png' style='height:60px;margin-bottom:16px;' alt='NIRVANA MART'><h1 style='color:#e8b86d;margin:0;font-size:1.5rem;'>Welcome to NIRVANA MART! 🎉</h1><p style='color:rgba(255,255,255,0.7);margin:8px 0 0;'>Your campus marketplace awaits</p></div><div style='background:white;padding:24px;border-radius:10px;margin-bottom:20px;'><p style='color:#333;font-size:1rem;'>Hi <strong>${$json.body.name}</strong>,</p><p style='color:#555;line-height:1.7;'>You've just joined NIRVANA MART — the smartest way to buy and sell on campus. Here's how to get started:</p><div style='background:#f9f9f9;border-radius:8px;padding:16px;margin:16px 0;'><p style='margin:8px 0;color:#333;'>🛍️ <strong>Browse Products</strong> — Find deals from fellow students</p><p style='margin:8px 0;color:#333;'>📦 <strong>List Your Items</strong> — Turn unused stuff into cash</p><p style='margin:8px 0;color:#333;'>🏫 <strong>Campus Corners</strong> — Hostel, Academic & Engineering stores</p><p style='margin:8px 0;color:#333;'>❤️ <strong>Wishlist</strong> — Save items you love</p></div></div><div style='text-align:center;margin-bottom:24px;'><a href='https://nirvana-mart.onrender.com/shop' style='display:inline-block;background:#c8923a;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-weight:700;font-size:1rem;margin-right:12px;'>Browse Products →</a></div><p style='color:#aaa;font-size:0.78rem;text-align:center;'>NIRVANA MART — Campus Marketplace | VIIT</p></div>`) }}
}

